/**
 * Animált Magyarország-térkép háttér (fuvarutak, szomszédos országhatárok,
 * néhány nagyváros felirata) — a Landing hero és a Login (desktop) közös
 * háttér-motívuma. Alapból csak md+ nézetben látszik (mobilon nincs elég
 * hely ahhoz, hogy rendesen megjelenjen).
 */
export default function HungaryMapBackground({
  fadeToColor = "#F2F3F5",
  showBottomFade = true,
  className = "",
}) {
  return (
    <div className={`absolute inset-0 overflow-hidden hero-map-in hidden md:block ${className}`}>
      <style>{`
        @keyframes routeFlow {
          to { stroke-dashoffset: -200; }
        }
        @keyframes waypointPulse {
          0%, 100% { opacity: 0.45; transform: scale(1); }
          50% { opacity: 0.85; transform: scale(1.3); }
        }
        @keyframes heroMapIn {
          from { opacity: 0; transform: scale(1.06); filter: blur(14px); }
          to { opacity: 1; transform: scale(1); filter: blur(0); }
        }
        @keyframes orbFloat {
          0%, 100% { transform: translate(0, 0); }
          50% { transform: translate(-14px, 22px); }
        }
        @keyframes orbFloatDelay {
          0%, 100% { transform: translate(0, 0); }
          50% { transform: translate(18px, -18px); }
        }
        .route-flow-1 { animation: routeFlow 14s linear infinite; }
        .route-flow-2 { animation: routeFlow 22s linear infinite reverse; }
        .route-flow-3 { animation: routeFlow 18s linear infinite; }
        .route-flow-4 { animation: routeFlow 26s linear infinite reverse; }
        .route-flow-5 { animation: routeFlow 16s linear infinite; }
        .waypoint-pulse {
          transform-box: fill-box;
          transform-origin: center;
          animation: waypointPulse 4s ease-in-out infinite;
        }
        .waypoint-pulse-delay { animation-delay: 1.8s; }
        .hero-map-in { animation: heroMapIn 1.6s cubic-bezier(0.16, 1, 0.3, 1) both; }
        .hero-map-orb-1 { animation: orbFloat 9s ease-in-out infinite; }
        .hero-map-orb-2 { animation: orbFloatDelay 11s ease-in-out infinite; }
        @media (prefers-reduced-motion: reduce) {
          .route-flow-1, .route-flow-2, .route-flow-3, .route-flow-4, .route-flow-5, .waypoint-pulse,
          .hero-map-in, .hero-map-orb-1, .hero-map-orb-2 {
            animation: none;
          }
        }
      `}</style>
      <div
        className="absolute inset-0"
        style={{
          background:
            "radial-gradient(ellipse 900px 550px at 85% -10%, rgba(30,58,168,0.10), transparent 60%)",
        }}
      ></div>
      <svg
        viewBox="0 0 1440 900"
        preserveAspectRatio="xMidYMid slice"
        className="absolute inset-0 w-full h-full"
      >
        {/* Szomszédos országok határai — nagyon halványan, csak
            regionális kontextust adnak Magyarország köré. */}
        {HERO_NEIGHBORS.map((d, i) => (
          <path
            key={i}
            d={d}
            fill="#23262B"
            fillOpacity="0.02"
            stroke="#23262B"
            strokeWidth="1"
            strokeOpacity="0.08"
          />
        ))}
        {/* Magyarország határa — halványan a háttérbe olvadva, csak
            annyira látszik, hogy felismerhető legyen. */}
        <path
          d={HUNGARY_BORDER_PATH}
          fill="#23262B"
          fillOpacity="0.045"
          stroke="#23262B"
          strokeWidth="1.5"
          strokeOpacity="0.16"
        />
        {/* Fuvarutak — hazai városok között és az országhatáron túl */}
        {HERO_ROUTES.map((route, i) => (
          <path
            key={i}
            className={route.speed}
            d={route.d}
            stroke={route.color}
            strokeWidth={route.color === "#1E3AA8" ? 2 : 1.5}
            strokeDasharray={route.dash}
            fill="none"
            opacity={route.opacity}
          />
        ))}
        {/* Csomópontok a városoknál — Budapest a fő elosztó */}
        <circle
          className="waypoint-pulse"
          cx={HERO_HUB.x}
          cy={HERO_HUB.y}
          r="5"
          fill="#1E3AA8"
          opacity="0.6"
        />
        <circle
          cx={HERO_HUB.x}
          cy={HERO_HUB.y}
          r="14"
          stroke="#1E3AA8"
          fill="none"
          opacity="0.25"
        />
        {HERO_WAYPOINTS.map((wp, i) => (
          <circle
            key={i}
            className={wp.pulse ? "waypoint-pulse waypoint-pulse-delay" : ""}
            cx={wp.x}
            cy={wp.y}
            r={wp.dim ? 3 : 4}
            fill={wp.dim ? "#23262B" : "#1E3AA8"}
            opacity={wp.dim ? 0.25 : wp.pulse ? 0.5 : 0.4}
          />
        ))}
        {/* Néhány nagyváros felirata */}
        {HERO_CITY_LABELS.map((city, i) => (
          <text
            key={i}
            x={city.x + 8}
            y={city.y + 4}
            fontSize="13"
            fontFamily="Overpass, sans-serif"
            fontWeight="600"
            fill="#23262B"
            opacity="0.38"
          >
            {city.label}
          </text>
        ))}
        {/* Néhány határon túli nagyváros felirata — halványabban */}
        {HERO_FOREIGN_CITY_LABELS.map((city, i) => (
          <text
            key={i}
            x={city.x + 7}
            y={city.y + 3}
            fontSize="11"
            fontFamily="Overpass, sans-serif"
            fontWeight="500"
            fontStyle="italic"
            fill="#23262B"
            opacity="0.24"
          >
            {city.label}
          </text>
        ))}
      </svg>
      <div className="hero-map-orb-1 absolute -top-24 -right-16 w-[28rem] h-[28rem] rounded-full bg-[#1E3AA8]/15 blur-3xl pointer-events-none"></div>
      <div className="hero-map-orb-2 absolute bottom-0 left-1/4 w-80 h-80 rounded-full bg-[#1E3AA8]/10 blur-3xl pointer-events-none"></div>
      <div
        className="absolute inset-0 bg-grain opacity-[0.05] mix-blend-overlay pointer-events-none"
      ></div>
      {showBottomFade && (
        <div
          className="absolute inset-x-0 bottom-0 h-56 pointer-events-none"
          style={{
            background: `linear-gradient(to bottom, transparent, ${fadeToColor})`,
          }}
        ></div>
      )}
    </div>
  );
}
